REASON = "pipeline reordered: Page Split removed, Dewarping now before Margins (#195)"


def remove_page_split_and_relink(apps, schema_editor):
    stage_states = apps.get_model("core", "ScanTailorStageState")
    page_versions = apps.get_model("core", "ScanPageVersion")
    alias = schema_editor.connection.alias
